import { useEffect, useRef, useState } from 'react'

const stats = [
  { value: 500, suffix: '+', label: 'عميل راضٍ', icon: '👥', color: '#0ea5e9' },
  { value: 98, suffix: '٪', label: 'نسبة رضا العملاء', icon: '⭐', color: '#f59e0b' },
  { value: 1200, suffix: '+', label: 'مشروع مكتمل', icon: '🚀', color: '#8b5cf6' },
  { value: 5, suffix: ' سنوات', label: 'خبرة في السوق', icon: '🏆', color: '#22c55e' },
]

function useCounter(target: number, duration = 2000, started: boolean) {
  const [count, setCount] = useState(0)
  useEffect(() => {
    if (!started) return
    let start = 0
    const step = target / (duration / 16)
    const timer = setInterval(() => {
      start += step
      if (start >= target) {
        setCount(target)
        clearInterval(timer)
      } else {
        setCount(Math.floor(start))
      }
    }, 16)
    return () => clearInterval(timer)
  }, [target, duration, started])
  return count
}

function StatCard({ stat, index, started }: { stat: typeof stats[0]; index: number; started: boolean }) {
  const count = useCounter(stat.value, 2000, started)
  return (
    <div
      className="glass-card stat-card"
      style={{
        padding: '32px 24px',
        borderRadius: '20px',
        textAlign: 'center',
        animationDelay: `${index * 150}ms`,
      }}
    >
      <div style={{ fontSize: '36px', marginBottom: '12px' }}>{stat.icon}</div>
      <div style={{
        fontSize: 'clamp(32px, 4vw, 48px)',
        fontWeight: 900,
        color: stat.color,
        lineHeight: 1,
        marginBottom: '8px',
      }}>
        {count.toLocaleString('ar-SA')}{stat.suffix}
      </div>
      <div style={{ color: '#64748b', fontSize: '15px', fontWeight: 500 }}>{stat.label}</div>
    </div>
  )
}

export default function Stats() {
  const ref = useRef<HTMLDivElement>(null)
  const [started, setStarted] = useState(false)

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setStarted(true) },
      { threshold: 0.3 }
    )
    if (ref.current) observer.observe(ref.current)
    return () => observer.disconnect()
  }, [])

  return (
    <section ref={ref} style={{ padding: '80px 24px', position: 'relative', zIndex: 1 }}>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
          gap: '24px',
        }} className="section-reveal">
          {stats.map((s, i) => <StatCard key={s.label} stat={s} index={i} started={started} />)}
        </div>
      </div>
    </section>
  )
}

