        {links.map((l) => (
          <a key={l.href} href={l.href} style={{
            color: '#94a3b8', textDecoration: 'none', padding: '6px 14px',
            borderRadius: '8px', fontSize: '14px', fontWeight: 500,
            transition: 'all 0.2s ease',
          }}
          onMouseEnter={(e) => {
            (e.target as HTMLElement).style.color = '#0ea5e9'
            ;(e.target as HTMLElement).style.background = 'rgba(14,165,233,0.08)'
          }}
          onMouseLeave={(e) => {
            (e.target as HTMLElement).style.color = '#94a3b8'
            ;(e.target as HTMLElement).style.background = 'transparent'
          }}>
            {l.label}
          </a>
        ))}
      </div>

      {/* CTA */}
      <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
        <a href="#contact" style={{
          padding: '8px 20px', borderRadius: '10px', fontSize: '14px',
          fontWeight: 600, cursor: 'pointer', textDecoration: 'none',
          color: '#0ea5e9', border: '1px solid rgba(14,165,233,0.4)',
          transition: 'all 0.3s',
          display: 'none',
        }} className="btn-outline">
          تواصل معنا
        </a>
        <a href="#pricing" className="neon-btn" style={{
          padding: '8px 22px', borderRadius: '10px', fontSize: '14px',
          fontWeight: 600, cursor: 'pointer', textDecoration: 'none',
          color: 'white',
        }}>
          ابدأ الآن
        </a>
      </div>
    </nav>
  )
}
